local function index(id) if type(id)=='number' then return (id-1)%#profiles+1 end; local number=tonumber(tostring(id):match('(%d+)$')); if number then return (number-1)%#profiles+1 end; local hash=0; for byte in tostring(id):gmatch('.') do hash=(hash*31+byte:byte())%997 end; return hash%#profiles+1 end
function Ch.profile(id) return profiles[index(id)] end
local function woven(x,y,w,h,produce) O.polygon({x+6,y,x+w-6,y,x+w,y+h,x,y+h},T.wood,3); for line=1,5 do O.line({x+2,y+line*h/6,x+w-2,y+line*h/6},T.mustard,1.2) end; for line=1,5 do O.line({x+line*w/6,y+3,x+line*w/6,y+h-3},T.mustard,1); end; O.line({x+12,y+6,x+12,y-14,x+w-12,y-14,x+w-12,y+6},T.darkwood,2); if produce then for i=1,5 do O.ellipse(x+8+i*w/7,y-3-i%2*4,7,9,i%2==0 and T.sage or T.mustard,.8) end end end
