local function hairFront(p,hair) local top=p.cy-p.ry; if p.hair=='bald' then O.line({120-p.rx+3,p.cy-23,120-p.rx+8,p.cy-42},hair,4); O.line({120+p.rx-3,p.cy-23,120+p.rx-8,p.cy-42},hair,4)
 elseif p.hair=='curly' then for i=0,6 do O.ellipse(75+i*15,top+10+i%2*6,13,15,hair) end
 elseif p.hair=='wrap' then O.polygon({68,top+40,78,top-2,118,top-15,160,top,171,top+42,140,top+18,108,top+12},T.mustard); O.line({86,top+4,148,top+25},T.paper,2)
