 elseif p.hair=='sidepart' then O.polygon({77,top+31,80,top+3,110,top-10,151,top-2,163,top+22,125,top+10,100,top+30},hair); O.line({125,top+3,119,top+22},T.wood,.8)
 elseif p.hair=='pixie' then O.polygon({76,top+26,83,top-1,115,top-12,133,top-3,162,top-1,158,top+29,142,top+15,125,top+29,111,top+15,96,top+27},hair)
