 elseif p.hair=='wavy' then for i=0,5 do O.ellipse(80+i*16,top+10+i%2*5,13,14,hair) end else O.polygon({120-p.rx,top+35,120-p.rx+6,top+7,113,top-9,151,top+2,120+p.rx,top+34,141,top+16,119,top+24,101,top+13},hair) end end
local function face(p,expression,skin) local cx=120; local cy=p.cy; local eye=cy+1; local gap=p.rx*.35; O.ellipse(cx,cy+17,p.nose,10+(p.nose-5)*.7,C.darken(skin,.08),1); g.setColor(T.ink); g.setLineWidth(1.5)
 if expression=='happy' then g.arc('line','open',cx-gap,eye+2,3.6,math.pi,2*math.pi); g.arc('line','open',cx+gap,eye+2,3.6,math.pi,2*math.pi); g.arc('line','open',cx,cy+29,11,.1,3); O.ellipse(cx-gap-5,cy+21,5,2,T.blush,.4); O.ellipse(cx+gap+5,cy+21,5,2,T.blush,.4)
 else g.circle('fill',cx-gap,eye,2+p.rx/80); g.circle('fill',cx+gap,eye,2+p.rx/80); if expression=='angry' then g.line(cx-gap-7,cy-12,cx-gap+6,cy-7); g.line(cx+gap-6,cy-7,cx+gap+7,cy-12); g.arc('line','open',cx,cy+46,10,3.4,6); for i=0,2 do O.line({77+i*20,cy-p.ry-16,74+i*20,cy-p.ry-24,78+i*20,cy-p.ry-31},T.dustyrose,1.5) end
 elseif expression=='impatient' then g.line(cx-gap-7,cy-10,cx-gap+6,cy-10); g.line(cx+gap-6,cy-9,cx+gap+7,cy-13); g.line(cx-8,cy+33,cx+7,cy+33); O.polygon({cx+p.rx+3,cy-25,cx+p.rx+8,cy-13,cx+p.rx+3,cy-8,cx+p.rx-2,cy-13},T.sky,.8)
 else g.line(cx-gap-7,cy-10,cx-gap+6,cy-11); g.line(cx+gap-6,cy-11,cx+gap+7,cy-10); g.arc('line','open',cx,cy+30,7,.25,2.9) end end
 if p.beard then O.polygon({120-p.rx+7,cy+27,91,cy+53,120,cy+62,151,cy+51,120+p.rx-6,cy+26,142,cy+40,119,cy+47,98,cy+39},T.ink); O.ellipse(107,cy+29,10,3,T.ink); O.ellipse(132,cy+29,10,3,T.ink) end
end
