 elseif a=='teacher' then glasses(p); O.rect(42,268,43,62,T.teal,3); O.line({49,272,78,272},T.paper,2); O.rect(119,neck+26,5,24,T.paper,1); O.ellipse(122,neck+53,3,3,T.mustard,.6)
