 elseif a=='rider' then O.polygon({64,p.cy-23,65,p.cy-p.ry-9,120,p.cy-p.ry-32,175,p.cy-p.ry-8,177,p.cy-23,153,p.cy-44,90,p.cy-44},T.sage); O.line({70,p.cy-23,120,p.cy+58,170,p.cy-23},T.teal,3); O.line({62,neck+9,178,321},T.darkwood,8); O.rect(157,281,64,48,T.wood,4); O.line({189,283,189,328},T.paper,6); O.line({163,295,215,295},T.paper,2)
 elseif a=='bayong' then woven(152,278,65,49,false); O.line({76,neck+10,162,302},T.darkwood,7); O.rect(91,neck+24,59,111,T.paper,6); O.rect(104,neck+72,33,26,T.blush,2)
