 elseif a=='lanyard' then O.line({95,neck+4,117,256,142,neck+4},T.maroon,3); O.rect(105,256,30,39,T.paper,3); O.ellipse(119,270,6,6,T.sky,.6); O.line({110,283,130,283},T.teal,1); O.polygon({94,neck-1,119,neck+23,104,neck+36,84,neck+10},T.paper); O.polygon({144,neck-1,121,neck+23,136,neck+36,154,neck+10},T.paper)
