local function render(p,expression) local skin=T.skinTones[p.skin]; local hair=p.hair=='silverbun' and T.steel or T.ink; local shirt=T[p.shirt]; hairBack(p,hair); local neck=p.cy+p.ry; local shoulder=neck+7; local left=120-p.shoulder; local right=120+p.shoulder; O.polygon({84,shoulder,156,shoulder,right-5,shoulder+12,right+10,267,right,330,left,330,left-10,267,left+5,shoulder+12},shirt); O.ellipse(left+16,277,21,48,shirt); O.ellipse(right-16,277,21,48,shirt); O.polygon({left+11,shoulder+29,left+24,shoulder+24,left+32,310,left+17,310},C.darken(shirt,.08)); O.line({right-27,shoulder+37,right-20,290,right-29,308},C.darken(shirt,.13),2); O.line({104,312,140,312},C.darken(shirt,.1),1.5); O.rect(105,neck-15,30,40,skin,10); O.ellipse(120-p.rx-6,p.cy+3,10,15,skin); O.ellipse(120+p.rx+6,p.cy+3,10,15,skin); O.ellipse(120,p.cy,p.rx,p.ry,skin,1.2); hairFront(p,hair); face(p,expression,skin); details(p,shirt); O.ellipse(left+17,318,20,11,skin); O.ellipse(right-17,318,20,11,skin); O.line({left+8,318,left+23,319},C.shade(skin),1); O.line({right-23,319,right-8,318},C.shade(skin),1) end
function Ch.draw(id,x,y,scale,expression) scale=scale or 1; expression=expression or 'waiting'; if expression=='neutral' then expression='waiting' end; local n=index(id); local base=L.scale*love.window.getDPIScale(); local baseKey=string.format('%.3f',base); if currentDensity~=baseKey then cache={}; currentDensity=baseKey end; local density=base*scale; local key=n..':'..expression..':'..string.format('%.3f',density); local canvas=cache[key]; if not canvas then canvas=g.newCanvas(math.ceil(240*density),math.ceil(340*density)); local previous=g.getCanvas(); g.push('all'); g.setCanvas(canvas); g.origin(); g.setScissor(); g.clear(0,0,0,0); g.scale(density); render(profiles[n],expression); g.setCanvas(previous); g.pop(); cache[key]=canvas end; g.push('all'); g.setBlendMode('alpha','premultiplied'); g.setColor(1,1,1,1); g.draw(canvas,x,y,0,scale/density,scale/density); g.pop() end
function Ch.clear() cache={}; currentDensity=nil end
return Ch

